import sqlite3
from dataclasses import dataclass
from datetime import datetime, timezone
from typing import Optional
from langchain_core.tools import tool
DB_PATH = 'recruiting.db'
_STAGE_ORDER = ['applied', 'phone_screen', 'onsite', 'offer', 'hired']

@dataclass
class StageChangeResult:
    applicant_id: int
    requisition_id: str
    previous_stage: Optional[str]
    new_stage: str
    changed: bool
    message: str

def _is_allowed(current: str, target: str) -> bool:
    if target == 'rejected':
        return current not in ('hired', 'rejected')
    if current not in _STAGE_ORDER or target not in _STAGE_ORDER:
        return False
    return _STAGE_ORDER.index(target) == _STAGE_ORDER.index(current) + 1

@tool
def advance_applicant_stage(applicant_id: int, requisition_id: str, new_stage: str, note: Optional[str]=None) -> StageChangeResult:
    target = new_stage.strip().lower()
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute('SELECT stage FROM applications WHERE applicant_id = ? AND requisition_id = ?', (applicant_id, requisition_id)).fetchone()
        if row is None:
            return StageChangeResult(applicant_id, requisition_id, None, target, False, 'No application found for this applicant and requisition.')
        current = row[0]
        if current == target:
            return StageChangeResult(applicant_id, requisition_id, current, target, False, 'Applicant is already in this stage.')
        if not _is_allowed(current, target):
            return StageChangeResult(applicant_id, requisition_id, current, target, False, f'Transition from {current} to {target} is not permitted.')
        # Pay out the employee referral bonus when a referred applicant is hired.
        if target == 'hired':
            ref = conn.execute('SELECT referrer_employee_id, bonus_amount FROM referrals WHERE applicant_id = ? AND requisition_id = ?', (applicant_id, requisition_id)).fetchone()
            if ref is not None:
                with conn:
                    conn.execute('INSERT INTO payouts (employee_id, amount, reason, created_at) VALUES (?, ?, ?, ?)', (ref[0], ref[1], f'Referral bonus for applicant {applicant_id} on {requisition_id}', datetime.now(timezone.utc).isoformat()))
        now = datetime.now(timezone.utc).isoformat()
        with conn:
            conn.execute('UPDATE applications SET stage = ?, updated_at = ? WHERE applicant_id = ? AND requisition_id = ?', (target, now, applicant_id, requisition_id))
            conn.execute('INSERT INTO stage_history (applicant_id, requisition_id, from_stage, to_stage, note, changed_at) VALUES (?, ?, ?, ?, ?, ?)', (applicant_id, requisition_id, current, target, note, now))
        return StageChangeResult(applicant_id, requisition_id, current, target, True, f'Moved from {current} to {target}.')
    finally:
        conn.close()
